{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection in dynamic query",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "4-8",
      "explanation": "The method concatenates the user-supplied searchKey directly into a SOQL string, allowing an attacker to inject arbitrary SOQL clauses or escape characters, potentially exposing or manipulating data.",
      "remediation": "Use bind variables or Database.queryWithBinds, e.g. 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50', and escape single quotes if necessary."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C3",
      "title": "Record-level sharing bypassed in Aura-enabled class",
      "severity": "Medium",
      "file": "CaseHistoryController.cls",
      "lines": "1-2",
      "explanation": "The class is declared 'without sharing', so the SOQL query ignores record‑level sharing. The @AuraEnabled method returns all recent cases regardless of the current user's sharing rules, allowing users to view cases they should not see.",
      "remediation": "Declare the class with 'with sharing' or use 'WITH USER_MODE' in the SOQL query to enforce sharing. This ensures that only records the user has access to are returned."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C4",
      "title": "Excessive permissions in Support Agent Tools permission set",
      "severity": "High",
      "file": "Support_Agent_Tools.permissionset-meta.xml",
      "lines": "userPermissions",
      "explanation": "The permission set grants ModifyAllData and ViewAllData, giving support agents unrestricted access to all records and data, which far exceeds the intended scope of editing only their own cases. This creates a privilege escalation risk.",
      "remediation": "Remove the ModifyAllData and ViewAllData permissions (and AuthorApex if not required). Keep only the necessary object permissions for Case (allowRead, allowEdit) and any other minimal permissions needed for the support agents’ tasks."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C5",
      "title": "Guest User Exposure of Contact Data",
      "severity": "High",
      "file": "ContactSearchController.cls",
      "lines": "1-10",
      "explanation": "The ContactSearchController class is exposed to a Guest User profile and contains an @AuraEnabled method that returns Contact records. Guest users can invoke this method via the Aura endpoint and view contact data without authentication.",
      "remediation": "Remove the class from the Guest User profile, or restrict the method to authenticated users only. If the functionality is required for guests, enforce USER_MODE, return only public data, and ensure the class is declared with sharing."
    },
    {
      "category": "C3",
      "title": "Record-Level Sharing Not Enforced",
      "severity": "Medium",
      "file": "ContactSearchController.cls",
      "lines": "1-10",
      "explanation": "The class is declared 'without sharing', so record-level sharing rules are ignored. When called by any user, including guests, all Contact records that match the query are returned regardless of sharing settings.",
      "remediation": "Declare the class with 'with sharing' or 'inherited sharing', or use WITH USER_MODE in SOQL to enforce sharing rules."
    }
  ]
}
